function swapAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];
  let i = 0;
  while (i < words.length) {
    if (words[i].match(/^(a|an|the)\s+(\w+)$/)) {
      adjectives.push(words[i]);
      i++;
    } else {
      i++;
    }
  }
  const newSentence = adjectives.join(" ") + " " + words.slice(adjectives.length).join(" ");
