To display a matrix as a bitmap with a zoom feature in Qt, you can use the QPainter and QMatrix classes. Here's a simple example:

1. Create a class that represents your matrix:
```cpp
class Matrix {
public:
    Matrix(int rows, int cols) : rows_(rows), cols_(cols) {
        data_ = new int[rows * cols];
    }

    ~Matrix() {
        delete[] data_;
    }

    int get(int row, int col) const {
        return data_[row * cols + col];
    }

    void set(int row, int col, int value) {
        data_[row * cols + col] = value;
    }

private:
    int* data_;
    int rows_;
    int cols_;
};
```
1. Create a class that displays the matrix as a bitmap:
```cpp
class MatrixBitmap : public QWidget {
public:
    MatrixBitmap(Matrix& matrix, int width, int height) : matrix_(matrix), width_(width), height_(height) {}

protected:
    void paintEvent(QPaintEvent* event) override {
        QPainter painter(this);
        painter.setRenderHint(QPainter::Antialiasing);

        QMatrix matrix;
        matrix.scale(width_ / matrix_.rows(), height_ / matrix_.cols());

        for (int i = 0; i < matrix_.rows(); i++) {
            for (int j = 0; j < matrix_.cols(); j++) {
                int value = matrix_.get(i, j);
                painter.setBrush(QColor(value, value, value));
                painter.drawRect(i * matrix_.cols(), j * matrix_.rows(), 1, 1);
            }
        }
    }

private:
    Matrix& matrix_;
    int width_;
    int height_;
};
```
