```cpp
#include <iostream>
#include <string>
#include <sstream>

using namespace std;

// Recursive function to generate the Fibonacci sequence
int fibonacci(int n, int a, int b) {
    if (n == 1) {
        return a;
    } else if (n == 2) {
        return b;
    } else {
        return fibonacci(n - 1, b, a + b);
    }
}

int main() {
    string input;
    int num1, num2, num3;
    int sequenceLength;

    cout << "Enter the first two integers: ";
    getline(cin, input);
    istringstream iss(input);

    if (!(iss >> num1 >> num2)) {
        cerr << "Error: Invalid input. Please enter two integers separated by a space." << endl;
        return 1;
    }

    cout << "Enter the number of sequence elements to generate: ";
    cin >> sequenceLength;

    if (sequenceLength <= 0) {
        cerr << "Error: Invalid input. Please enter a positive integer." << endl;
        return 1;
    }

    cout << "Fibonacci sequence: ";
    for (int i = 0; i < sequenceLength; ++i) {
        cout << fibonacci(i + 1, num1, num2) << ", ";
    }
    cout << endl;

    return 0;
}
```

