To achieve this task, you can use Google Apps Script along with the Google Maps API. Here's a sample code snippet that demonstrates how to search for a place name in a column and store the latitude and longitude in other columns:

```javascript
function searchPlace() {
  var sheet = SpreadsheetApp.getActiveSheet();
  var dataRange = sheet.getRange("A1:C10"); // Assuming your data range is from A1 to C10
  var places = [];

  dataRange.forEach(function(row) {
    var placeName = row[0];
    var url = "https://maps.googleapis.com/maps/api/geocode/json?address=" + placeName;

    var response = UrlFetchApp.fetch(url);
    var data = JSON.parse(response).results[0];

    places.push({
      name: placeName,
      latitude: data.geometry.location.lat,
      longitude: data.geometry.location.lng
    });
  });

  sheet.getRange("D1:F10").setValues(places); // Assuming your output range is from D1 to F10
}
```

