1. In the Update method, update the visualizer based on the audio source's position:
```csharp
void Update()
{
    if (audioSource.isPlaying)
    {
        visualizerTime += Time.deltaTime;
        float progress = audioSource.time / audioSource.clip.length;
        float angle = progress * 360f;
        visualizerObject.transform.rotation = Quaternion.Euler(0f, 0f, angle);
        visualizerObject.GetComponent<Renderer>().material.color = visualizerColors[(int)(progress * visualizerColors.Length)];
    }
}
