To create a simple toast notification using React Context, follow these steps:

1. First, create a new file named `NotificationContext.js` and define the Context:

```javascript
import React from 'react';

const NotificationContext = React.createContext();

function NotificationProvider(props) {
  const [notifications, setNotifications] = React.useState([]);

  function addNotification(notification) {
    setNotifications([...notifications, notification]);
  }

  return (
    <NotificationContext.Provider value={{ notifications, addNotification }}>
      {props.children}
    </NotificationContext.Provider>
  );
}

export { NotificationContext, NotificationProvider };
```

2. Next, import the Context and Provider in your main application file:

```javascript
import React from 'react';
import ReactDOM from 'react-dom';
import NotificationContext from './NotificationContext';
import App from './App';

ReactDOM.render(
  <React.StrictMode>
    <NotificationContext.Provider>
      <App />
    </NotificationContext.Provider>
  </React.StrictMode>,
  document.getElementById('root')
);
```

3. Now, you can use the NotificationContext in any component by wrapping it in the `NotificationProvider`. For example, let's create a simple Toast component:

```javascript
import React, { useContext } from 'react';
import { NotificationContext } from './NotificationContext';

function Toast({ message }) {
  const { notifications, addNotification } = useContext(NotificationContext);

  function handleClick() {
    addNotification({
      message,
      type: 'success', // or 'error', 'warning', etc.
      duration: 3000, // duration in milliseconds
    });
  }

  return (
    <div className="toast">
      <p>{message}</p>
      <button onClick={handleClick}>Close</button>
    </div>
  );
}

export default Toast;
```

